//! Regenerates the tables of `lez/RESULTS.md` (Stages 1, 4 and 5) into `lez/results/`.
//!
//! Run from `lez/` (see `RESULTS.md` for the environment):
//! `cargo run -p harness --bin tables`

use std::fs;

use harness::{attest, render, render_transitions, scenarios, TxReport};

fn main() {
    let dir = harness::results_dir();
    fs::create_dir_all(&dir).unwrap();
    let write = |name: &str, title: &str, reports: &[TxReport]| {
        let text = format!(
            "# {title}\n\nGenerated by `cargo run -p harness --bin tables` (see `../RESULTS.md`).\n\n{}\n## Every handler execution\n\n{}",
            render(reports),
            render_transitions(reports)
        );
        fs::write(dir.join(name), text).unwrap();
        println!("wrote results/{name}");
    };
    let images = format!(
        "# Guest images measured\n\nBuilt by `methods/` with RISC Zero Rust 1.91.1 (risc0-build 3.0.5).\n\n| guest | image id | ELF bytes |\n|---|---|---:|\n| program (`guests/program`) | `{}` | {} |\n| consumer (`guests/consumer`) | `{}` | {} |\n| LEZ's `scripted` (`guests/scripted`) | `{}` | {} |\n| comparison only: the program with software Keccak (`guests/program-keccak-soft`) | `{}` | {} |\n| comparison only: the consumer with accelerated Keccak (`guests/consumer-keccak-accel`) | `{}` | {} |\n",
        harness::image_id_hex(methods::FERRATA_LEZ_ID),
        methods::FERRATA_LEZ_ELF.len(),
        harness::image_id_hex(methods::FERRATA_CONSUMER_ID),
        methods::FERRATA_CONSUMER_ELF.len(),
        harness::image_id_hex(methods::SCRIPTED_ID),
        methods::SCRIPTED_ELF.len(),
        harness::image_id_hex(methods::FERRATA_LEZ_KECCAK_SOFT_ID),
        methods::FERRATA_LEZ_KECCAK_SOFT_ELF.len(),
        harness::image_id_hex(methods::FERRATA_CONSUMER_KECCAK_ACCEL_ID),
        methods::FERRATA_CONSUMER_KECCAK_ACCEL_ELF.len(),
    );
    fs::write(dir.join("images.md"), images).unwrap();
    println!("wrote results/images.md");
    let replay = scenarios::replay(2);
    write(
        "stage1-replay.md",
        &format!("Init and the five mainnet updates, as LEZ {} charges them", harness::LEZ_TAG),
        &replay.chain.reports,
    );
    let finality = scenarios::finality_path();
    write(
        "stage1-finality.md",
        "A finality update (three transactions) and an update that only hands over a committee",
        &finality.chain.reports[8..],
    );
    let refusals: Vec<TxReport> =
        scenarios::refusals().into_iter().map(|r| TxReport { label: r.case.to_string(), ..r.report }).collect();
    write("stage1-refusals.md", &format!("Refusals, as LEZ {} charges them", harness::LEZ_TAG), &refusals);
    write(
        "shell-costs.md",
        "What the LEZ v0.4 shell costs: a public read, and calls with growing messages",
        &scenarios::shell_costs(),
    );
    write(
        "stage1-one-transaction.md",
        "A finality update verified in one public transaction",
        &scenarios::one_transaction_update(),
    );

    // Stage 4: attestation on the mainnet fixture of 10 November 2026.
    let (_, accepted) = attest::accepted();
    write(
        "stage4-attest.md",
        "Attestations under the record of mainnet block 26,384,851, each sent as a transaction's root",
        &accepted,
    );
    let (_, soft) = attest::accepted_at(harness::KECCAK_SOFT);
    write(
        "stage4-attest-keccak-soft.md",
        "The same attestations by the program built without the accelerated Keccak",
        &soft,
    );
    let (_, consumer) = attest::consumer_path();
    write(
        "stage4-attest-consumer.md",
        "The public consumer path: a caller that keeps the reply, and the reference consumer's claim",
        &consumer,
    );
    let refusals: Vec<TxReport> =
        attest::refusals().into_iter().map(|r| TxReport { label: r.case.to_string(), ..r.report }).collect();
    write("stage4-attest-refusals.md", "Refusals of the attestation and of the reference consumer", &refusals);

    // The private path's cost for the consumer: its two transitions in the executor, for the
    // ordinary receipt and for the block's largest one.
    let s = attest::Stage4::new();
    let pool = s.pool();
    let slot = s.fx.finalized_slot;
    let account = lee::AccountId::new([0x81; 32]);
    let mut text = String::from(
        "# The private attestation path: the consumer's transitions in the executor\n\n\
         Generated by `cargo run -p harness --bin tables` (see `../RESULTS.md`). RISC Zero executor only, \
         no proof. The consumer (`guests/consumer`) verifies with software Keccak; the second table of \
         each case is the comparison build with RISC Zero's accelerated Keccak \
         (`guests/consumer-keccak-accel`), whose Keccak-f permutations a separate circuit would have to \
         prove. LEZ's privacy-preserving circuit, which a real proof also covers, is not in these counts.\n",
    );
    for (title, log) in [
        (format!("An ERC-20 Transfer in a receipt with {} logs", s.fx.transfer.logs_in_receipt), s.fx.transfer.clone()),
        (
            format!("A Transfer in the block's largest receipt ({} logs)", s.fx.in_largest.logs_in_receipt),
            s.fx.in_largest.clone(),
        ),
    ] {
        let pool = harness::attest::pool_for(&pool, &log);
        let message = s.private_message(&pool, slot, &log);
        let executed = s.private_transitions(account, slot, &message);
        let accelerated = s.private_transitions_of(&harness::consumer_keccak_accel_program(), account, slot, &message);
        for run in [&executed, &accelerated] {
            assert!(run.iter().all(|e| e.exit_code == 0), "{title}");
        }
        let total = |run: &[attest::Executed]| harness::grouped(run.iter().map(|e| e.cycles).sum());
        text.push_str(&format!(
            "\n## {title}\n\n{}\nTogether {} user cycles (software Keccak).\n\n\
             With the accelerated Keccak:\n\n{}\nTogether {} user cycles.\n",
            attest::render_executed(&executed),
            total(&executed),
            attest::render_executed(&accelerated),
            total(&accelerated),
        ));
    }
    fs::write(dir.join("stage4-attest-private.md"), text).unwrap();
    println!("wrote results/stage4-attest-private.md");

    // Stage 5: Sepolia through its Gloas fork, attestation under a Gloas record, accumulator
    // leaves in the guest.
    let (s5, accepted, refused) = harness::sepolia::attestations();
    let reports = &s5.w.chain.reports;
    let replay = &reports[..reports.len() - accepted.len() - refused.len()];
    let sum = |f: &dyn Fn(&TxReport) -> u64, rs: &[&TxReport]| harness::grouped(rs.iter().map(|r| f(r)).sum());
    let all: Vec<&TxReport> = replay.iter().collect();
    let period =
        |p: u64| -> Vec<&TxReport> { replay.iter().filter(|r| r.label.starts_with(&format!("period {p} "))).collect() };
    let mut text = format!(
        "# Sepolia through its Gloas fork, as LEZ v0.4.0-rc1 charges it\n\n\
         Generated by `cargo run -p harness --bin tables` (see `../RESULTS.md`). `Init` from the bootstrap \
         of period 1378 (Fulu era, Electra layout), every period's update to 1409 as a public job \
         (`Open`, `Miller`, two adoption parts, `Finish`), each in the layout the beacon node served it \
         in, then the finality update of `fixtures/sepolia-attest-2026-11-10`. The store upgrades itself \
         to the Gloas layout when the job of period 1379 is applied.\n\n\
         Totals of the {} transactions: execution gas {}, storage gas {}, transaction bytes {}.\n\n\
         ## The upgrade's cost: the jobs of the last Electra period, of the first Gloas period (the \
         upgrade) and of the next\n\n",
        all.len(),
        sum(&|r| r.charge.gas_exec, &all),
        sum(&|r| r.charge.gas_stor, &all),
        sum(&|r| r.tx_bytes as u64, &all),
    );
    for p in [1378, 1379, 1380] {
        let rs = period(p);
        let owned: Vec<TxReport> = rs.iter().map(|r| (*r).clone()).collect();
        text.push_str(&format!(
            "### period {p}: execution gas {}, storage gas {}\n\n{}\n",
            sum(&|r| r.charge.gas_exec, &rs),
            sum(&|r| r.charge.gas_stor, &rs),
            render(&owned)
        ));
    }
    text.push_str(&format!("## Every transaction\n\n{}", render(replay)));
    fs::write(dir.join("stage5-sepolia-replay.md"), text).unwrap();
    println!("wrote results/stage5-sepolia-replay.md");
    write(
        "stage5-attest.md",
        "Attestations under a Gloas record: Sepolia block 12,105,936, each request with the block's RLP header",
        &accepted,
    );
    write("stage5-attest-refusals.md", "Refusals under the Gloas record", &refused);
    let (vault_accepted, vault_refused) = harness::vault::synthetic_attestations();
    write(
        "stage5-vault-synthetic.md",
        "Accumulator leaves through the program: the vault's request on a synthetic state (the vault's \
         eight deposits) under a Gloas record",
        &[vault_accepted, vault_refused].concat(),
    );
}
